"""Record the color, motif and spacing decisions using the book's real HTML."""
from pathlib import Path
import re,json
from playwright.sync_api import sync_playwright
from PIL import Image,ImageDraw
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'previews/yearbook-color';PROTO=OUT/'prototype'
source=(PROTO/'index.html').read_text();css=re.search(r'<style>(.*?)</style>',source,re.S).group(1)
audit=json.loads((OUT/'content-audit.json').read_text())
extra='''
.study-body{position:absolute;left:38pt;right:38pt;top:87pt}.study-body h1{font-size:37pt;margin-bottom:22pt}.study-body h2{font-size:23pt;margin:24pt 0 13pt}.study-body p{font-size:11.5pt;line-height:1.5}.concept{width:519pt;height:351pt;object-fit:contain;margin:20pt 0}.study-caption{font:8pt Mono!important;color:var(--muted)}.swatches{display:grid;grid-template-columns:repeat(6,1fr);gap:10pt;margin:27pt 0 9pt}.swatch b{height:43pt;display:block}.swatch span{font:7.2pt Mono;display:block;margin-top:8pt}.specimen{padding:18pt 0;border-bottom:.5pt solid var(--line)}.specimen .meta{font:8pt Mono;color:var(--muted);margin-bottom:12pt}.display-spec{font:35pt Fraunces!important}.italic-spec{font:26pt FrauncesItalic!important}.body-spec{font:11.5pt Manrope!important}.mono-spec{font:8.2pt Mono!important;letter-spacing:.2pt}.rules{display:grid;grid-template-columns:137pt 1fr;gap:22pt;padding:17pt 0;border-bottom:.5pt solid var(--line)}.rules dt{font:17pt FrauncesText}.rules dd{font-size:11pt;line-height:1.55}@media print{.native-art{visibility:visible}}
'''
def page(body,n):return f'<section class="page"><header><span>AK20 / COLOR STUDY</span><span>DESIGN NOTES</span></header><div class="study-body">{body}</div><footer><span>DESIGN SYSTEM / PRINT PROOF</span><span class="folio">{n:02}</span></footer></section>'
first=page('''<h1>Color and shapes.</h1><p>Six experiments for the yearbook: rosettes, loops, a scalloped mount, a wave divider, a margin pattern, and an arc-and-dot composition.</p><img class="concept" src="../shape-exploration.png" alt="Image-tool shape exploration"><h2>Selected for the book</h2><p>Rosettes hold the year or a profile number. Loops and small corner shapes add lightness between content groups. Broad, flat color fields separate chapters and bring each person’s photos and anecdotes together.</p><p class="study-caption" style="margin-top:22pt">Built-in image generation supplied the visual experiments.<br>The selected shapes are implemented as vector artwork in the book.</p>''',1)
colors=[('INK','#30243B'),('PAPER','#FBF5E9'),('PROFILE','#BD503A'),('PHOTOS','#8BB9C7'),('TEACHERS','#EDCD57'),('QUOTES','#BAA1D0')]
swatches=''.join(f'<div class="swatch"><b style="background:{code}"></b><span>{name}<br>{code}</span></div>' for name,code in colors)
second=page(f'''<h1>Color has a role.</h1><p>Four chapter colors connect the contents, page tabs and section headers. Lighter variations support the photographs and text, with dark ink used throughout.</p><div class="swatches">{swatches}</div><div class="specimen"><p class="meta">FRAUNCES DISPLAY · TITLES AND NAMES</p><p class="display-spec">Klasse 10a. 2020.</p></div><div class="specimen"><p class="meta">FRAUNCES ITALIC · SMALL ACCENTS</p><p class="italic-spec">Typische Eigenschaften:</p></div><div class="specimen"><p class="meta">MANROPE · BODY 11–11.5 PT</p><p class="body-spec">Original names, dates, plans, anecdotes and quotes. Reading text has a consistent scale, comfortable line lengths, and enough space between separate conversations.</p></div><div class="specimen"><p class="meta">IBM PLEX MONO · LABELS AND CAPTIONS</p><p class="mono-spec">KINDERFOTO / KLASSE 10a / GEBOREN AM</p></div>''',2)
fourth=page(f'''<h1>Grouping and spacing.</h1><dl><div class="rules"><dt>Sectioning</dt><dd>Steckbriefe, Fotos, Unsere Lehrer and Historische Zitate. Their names and colors match in the contents, running headers and bookmarks.</dd></div><div class="rules"><dt>Proximity</dt><dd>Name, nickname and both photographs share one tinted area. Captions sit close to the picture edges. Biographical rows form a separate group; anecdotes follow after a 20 pt gap.</dd></div><div class="rules"><dt>Hierarchy</dt><dd>Serif names lead. Reading text is 11–11.5 pt; labels are 8.2 pt. The original “Typische Eigenschaften:” becomes the anecdote heading, replacing added filler copy.</dd></div><div class="rules"><dt>Whitespace</dt><dd>38 pt outside margins. Photo baselines and caption positions align. The anecdote panel has 16 pt inner padding. Dialogue stays together, with quote columns balanced by their measured heights.</dd></div><div class="rules"><dt>Motifs</dt><dd>The eight-petal rosette carries profile, teacher or year numbers. Small loops and quarter-circle corners share one restrained visual vocabulary. Background fields have one gently curved corner.</dd></div><div class="rules"><dt>Verification</dt><dd>52 A4 pages; all 215 content units and 88 photo placements checked. {audit['html_pdf_matched_text_spans']:,} HTML/PDF text-position matches; maximum drift {audit['maximum_type_position_drift_pt']} pt. Both earlier editions are unchanged.</dd></div></dl>''',4)
with sync_playwright() as p:
 b=p.chromium.launch(headless=True,args=['--no-sandbox']);t=b.new_page(viewport={'width':1650,'height':1250})
 t.goto((PROTO/'index.html').as_uri());t.evaluate('document.fonts.ready');third=t.locator('.page').nth(2).evaluate('(e)=>e.outerHTML')
 path=PROTO/'design-system.html';path.write_text('<html lang="en"><meta charset="utf-8"><title>AK20 Color Design Study</title><style>'+css+extra+'</style><main>'+first+second+third+fourth+'</main></html>')
 t.goto(path.as_uri());t.evaluate('document.fonts.ready');t.wait_for_function('Array.from(document.images).every(i=>i.complete)')
 for i in range(4):t.locator('.page').nth(i).screenshot(path=str(OUT/f'design-study-{i+1:02}.png'))
 t.emulate_media(media='print');t.pdf(path=str(OUT/'AK20-Farb-und-Formstudie.pdf'),prefer_css_page_size=True,print_background=True)
 b.close()
sheet=Image.new('RGB',(1304,451),'#DED7CF')
for i in range(4):
 im=Image.open(OUT/f'design-study-{i+1:02}.png').convert('RGB');im.thumbnail((298,422));tile=Image.new('RGB',(326,451),'#DED7CF');tile.paste(im,((326-im.width)//2,10));ImageDraw.Draw(tile).text((14,432),f'Study {i+1:02}',fill='#30243B');sheet.paste(tile,(i*326,0))
sheet.save(OUT/'design-study-preview.jpg',quality=94)
print(OUT/'AK20-Farb-und-Formstudie.pdf')
